<?php require_once '../config.php'; if((int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0) exit('An administrator already exists. Setup is disabled.');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10)$error='Use a name, valid email and password of at least 10 characters.';else{$s=db()->prepare('INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('Admin account created. Sign in now.');redirect('login.php');}}page_start('First-time admin setup');if($error)echo '<div class="alert error">'.e($error).'</div>';?><div class="alert warning">Create the factory owner account once. This page disables itself after the first admin is created.</div><form method="post" class="form panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Owner name<input name="name" required></label><label>Admin email<input type="email" name="email" required></label><label>Password (10+ characters)<input type="password" name="password" minlength="10" required></label><button class="btn">Create admin</button></form><?php page_end();?>
